  function zoom(scale){state.viewSpan=Math.max(3,Math.min(D.duration,state.viewSpan*scale));state.viewStart=Math.max(0,Math.min(D.duration-state.viewSpan,state.time-state.viewSpan*.33));const t=app.querySelector('[data-timeline]');if(t)t.innerHTML=window.VZ_INTERNAL.timelineContents();const label=app.querySelector('.timeline-window');if(label)label.textContent=format(state.viewStart,0)+' — '+format(state.viewStart+state.viewSpan,0);const z=app.querySelector('[data-control="zoom"]');if(z)z.value=state.viewSpan;}
