  document.addEventListener('click',e=>{const el=e.target.closest('[data-action],[data-cue],[data-nudge],[data-state],[data-audio],[data-settings],[data-provider]');if(!el)return;if(el.closest('.recent-project')&&e.target.closest('[data-action="project-menu"]'))e.stopPropagation();if(el.dataset.action){e.preventDefault();actions[el.dataset.action]?.(el);}else if(el.dataset.cue!==undefined){selectCue(Number(el.dataset.cue),true,e.shiftKey);}else if(el.dataset.nudge){retime(el.dataset.nudge,selected()[el.dataset.nudge]+Number(el.dataset.delta));}else if(el.dataset.state){applyFixture(el.dataset.state);}else if(el.dataset.audio){state.audioMode=el.dataset.audio;render();}else if(el.dataset.settings){state.settingsTab=el.dataset.settings;render();}else if(el.dataset.provider){dialog('Khóa API · '+esc(el.dataset.provider),`<label class="field-label">Khóa API<input class="field mono" type="password" placeholder="Dán khóa của dịch vụ" aria-label="Khóa API dịch vụ" autocomplete="off"></label><p style="font-size:10px">Thêm khóa để công cụ này xuất hiện là khả dụng trong danh sách.</p>`,[{label:'Hủy',action:'close-dialog'},{label:'Lưu khóa',action:'settings-save',cls:'primary'}]);}});
