  document.addEventListener('input',e=>{const el=e.target,id=el.dataset.control;if(!id){if(el.closest('.settings-content'))state.settingsDirty=true;return;}if(id==='vi'){selected().vi=el.value;changed();refreshEditor({inspector:false});}else if(id==='url')state.url=el.value;else if(id==='context-note')state.note=el.value;else if(id==='search'){state.search=el.value;refreshEditor({inspector:false});}else if(id==='replace')state.replace=el.value;else if(id==='gain'){selected().gain=Number(el.value);changed();const g=app.querySelector('[data-gain]');g.textContent=(el.value>0?'+':'')+el.value+' dB';}else if(id==='source-volume'){const v=app.querySelector('video');if(v)v.volume=Number(el.value)/100;}else if(id==='zoom'){state.viewSpan=Number(el.value);state.viewStart=Math.max(0,state.time-state.viewSpan*.33);const t=app.querySelector('[data-timeline]');t.innerHTML=window.VZ_INTERNAL.timelineContents();}else if(id==='voice-speed'){state.speed=Number(el.value);app.querySelector('[data-speed]').textContent=state.speed.toFixed(2)+'×';}else if(id==='original-volume'){state.originalVolume=Number(el.value);app.querySelector('[data-original-volume]').textContent=el.value+'%';}else if(id==='dub-volume'){state.volume=Number(el.value);app.querySelector('[data-dub-volume]').textContent=el.value+'%';}else if(id.startsWith('style-')){if(['style-size','style-color','style-outline'].includes(id)){const prop={'style-size':'size','style-color':'color','style-outline':'outline'}[id];window.VZ_INTERNAL.editStyle(prop,id==='style-color'?el.value:Number(el.value));}}else if(el.closest('.settings-content')){state.settingsDirty=true;}});
